const crypto = require('crypto');
const secret = process.env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET not set');
const rawBody = $input.first().binary?.data
  ? Buffer.from($input.first().binary.data, 'base64').toString()
  : JSON.stringify($input.first().json);
const incomingSig = $input.first().headers?.['x-mf-signature'] ?? '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
if (incomingSig.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(incomingSig), Buffer.from(expected))) {
  throw new Error('HMAC mismatch');
}
return $input.all();

const body = $input.first().json;
const required = ['org_id', 'content_item_id', 'prompt'];
const missing = required.filter(k => !body[k]);
if (missing.length) throw new Error(`Missing fields: ${missing.join(', ')}`);

return [{
  json: {
    org_id: body.org_id,
    content_item_id: body.content_item_id,
    prompt: body.prompt,
    negative_prompt: body.negative_prompt ?? '',
    aspect_ratio: body.aspect_ratio ?? '1:1',
    model: body.model_hint ?? 'fal-ai/ideogram/v3',
    count: Math.min(body.count ?? 1, 4),
  }
}];

const upstream = $('Validate Payload').first().json;
const falRes = $input.first().json;

// fal queue response: { status:'COMPLETED'|'IN_PROGRESS'|'FAILED', output:{ images:[{url,width,height}] } }
if (falRes.status === 'FAILED') {
  throw new Error(`fal generation failed: ${falRes.error ?? 'unknown'}`);
}
if (falRes.status !== 'COMPLETED') {
  throw new Error(`fal returned status '${falRes.status}' after polling — increase wait time`);
}

const images = (falRes.output?.images ?? falRes.images ?? []).map((img, i) => ({
  index: i,
  url: img.url ?? img.image_url ?? null,
  width: img.width ?? null,
  height: img.height ?? null,
  storageKey: null, // worker is responsible for uploading to S3 after receiving this
}));

return [{
  json: {
    org_id: upstream.org_id,
    content_item_id: upstream.content_item_id,
    model: upstream.model,
    images,
    usage: { credits: falRes.usage?.credits ?? null },
  }
}];
